// AI DISCLOSURE: Architecture, React components, and procedural data models generated by AI.
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import * as P from "./physics/lunarAstronomy";

/**
 * Landing simulator. Side view of a real LOLA terrain cross-section (east-west through the chosen lander row).
 * Rigid-body style physics: lunar gravity, a main engine along the body axis, attitude thrusters that apply
 * torque, and finite propellant. Touchdown is judged on speed, tilt and the slope of the ground under the feet.
 */

const G_MOON = 1.62; // m/s^2
const THRUST = 4.6; // m/s^2 at full throttle
const TORQUE = 2.4; // rad/s^2
const BURN_S = 30; // seconds of main-engine propellant
export const LIMITS = { vVert: 3, vHoriz: 2, tilt: 12, slope: P.SLOPE_LIMIT_DEG };

type Phase = "ready" | "fly" | "landed" | "crashed";
interface Result {
  ok: boolean;
  title: string;
  reasons: string[];
  grade: string;
  vVert: number;
  vHoriz: number;
  tilt: number;
  slope: number;
  fuel: number;
  sun: boolean;
  earth: boolean;
}

export function LanderGame(props: {
  site: P.Site;
  rowIy: number;
  grid: P.CellStatus[];
  sunAz: number;
  sunLit: boolean;
  earthVisible: boolean;
}) {
  const { site, rowIy, grid } = props;
  const cvRef = useRef<HTMLCanvasElement>(null);
  const keys = useRef({ l: false, r: false, t: false });
  const sim = useRef({ x: 0, y: 0, vx: 0, vy: 0, a: 0, w: 0, fuel: 1, scale: 0.5, burn: false });
  const phaseRef = useRef<Phase>("ready");
  const assistRef = useRef(true);
  const [assist, setAssist] = useState(true);
  const [phase, setPhaseState] = useState<Phase>("ready");
  const [hud, setHud] = useState({ alt: 0, vv: 0, vh: 0, tilt: 0, fuel: 1 });
  const [result, setResult] = useState<Result | null>(null);
  const setPhase = (p: Phase) => {
    phaseRef.current = p;
    setPhaseState(p);
  };

  const yRow = (rowIy - 10) * 100;
  const terrain = useMemo(() => {
    const n = 421;
    const h = new Float32Array(n);
    let top = -Infinity;
    for (let i = 0; i < n; i++) {
      h[i] = P.patchElevationAt(site, -1050 + i * 5, yRow);
      if (h[i] > top) top = h[i];
    }
    return { h, top };
  }, [site, yRow]);
  const ground = useCallback(
    (x: number) => {
      const f = P.clamp((x + 1050) / 5, 0, 419.999);
      const i = Math.floor(f);
      return terrain.h[i] + (terrain.h[i + 1] - terrain.h[i]) * (f - i);
    },
    [terrain]
  );
  const slopeAt = useCallback((x: number) => Math.atan((ground(x + 10) - ground(x - 10)) / 20) / P.DEG, [ground]);

  const reset = useCallback(() => {
    sim.current = { x: -720, y: terrain.top + 130, vx: 9, vy: 0, a: 0, w: 0, fuel: 1, scale: 0.5, burn: false };
    setResult(null);
    setPhase("ready");
  }, [terrain]);
  useEffect(reset, [reset]);

  const finish = useCallback(
    (outOfBounds: boolean) => {
      const s = sim.current;
      const vVert = Math.max(0, -s.vy);
      const vHoriz = Math.abs(s.vx);
      const tilt = Math.abs(s.a) / P.DEG;
      const slope = Math.abs(slopeAt(s.x));
      const reasons: string[] = [];
      if (outOfBounds) reasons.push("Drifted outside the mapped terrain");
      else {
        if (vVert > LIMITS.vVert) reasons.push(`Descent too fast: ${vVert.toFixed(1)} m/s (limit ${LIMITS.vVert})`);
        if (vHoriz > LIMITS.vHoriz) reasons.push(`Sliding sideways: ${vHoriz.toFixed(1)} m/s (limit ${LIMITS.vHoriz})`);
        if (tilt > LIMITS.tilt) reasons.push(`Tilted ${tilt.toFixed(0)}° at contact (limit ${LIMITS.tilt}°)`);
        if (slope > LIMITS.slope) reasons.push(`Ground too steep: ${slope.toFixed(0)}° slope, the lander tipped over`);
      }
      const ok = reasons.length === 0;
      const ix = P.clamp(Math.round((s.x + 1000) / 100), 0, P.GRID_N - 1);
      const cell = grid[rowIy * P.GRID_N + ix];
      const sun = cell.sunFrac > 0.5;
      const earth = cell.lock !== "BLACKOUT";
      const score =
        s.fuel * 40 + (1 - vVert / LIMITS.vVert) * 20 + (1 - vHoriz / LIMITS.vHoriz) * 10 + (1 - slope / LIMITS.slope) * 10 + (sun ? 10 : 0) + (earth ? 10 : 0);
      const grade = !ok ? "F" : score >= 72 ? "A" : score >= 55 ? "B" : "C";
      setResult({ ok, title: ok ? "TOUCHDOWN" : outOfBounds ? "SIGNAL LOST" : "LOSS OF VEHICLE", reasons, grade, vVert, vHoriz, tilt, slope, fuel: s.fuel, sun, earth });
      setPhase(ok ? "landed" : "crashed");
    },
    [grid, rowIy, slopeAt]
  );

  /* keyboard */
  useEffect(() => {
    const set = (e: KeyboardEvent, v: boolean) => {
      const k = e.key;
      let hit = true;
      if (k === "ArrowLeft" || k === "a" || k === "A") keys.current.l = v;
      else if (k === "ArrowRight" || k === "d" || k === "D") keys.current.r = v;
      else if (k === "ArrowUp" || k === "w" || k === "W" || k === " ") keys.current.t = v;
      else hit = false;
      if (hit && (e.target as HTMLElement)?.tagName !== "INPUT" && (e.target as HTMLElement)?.tagName !== "SELECT") {
        e.preventDefault();
        if (v && phaseRef.current === "ready") setPhase("fly");
      }
    };
    const dn = (e: KeyboardEvent) => set(e, true);
    const up = (e: KeyboardEvent) => set(e, false);
    window.addEventListener("keydown", dn);
    window.addEventListener("keyup", up);
    return () => {
      window.removeEventListener("keydown", dn);
      window.removeEventListener("keyup", up);
    };
  }, []);

  /* simulation + render loop */
  useEffect(() => {
    const cv = cvRef.current;
    const ctx = cv && cv.getContext("2d");
    if (!cv || !ctx) return;
    let raf = 0;
    let last = performance.now();
    let hudT = 0;
    const stars = Array.from({ length: 90 }, () => [Math.random(), Math.random() * 0.75, Math.random() * 1.1 + 0.3]);
    const sunRight = Math.sin(props.sunAz * P.DEG) >= 0;

    const frame = (ms: number) => {
      raf = requestAnimationFrame(frame);
      const dt = Math.min(0.04, (ms - last) / 1000);
      last = ms;
      const s = sim.current;
      const k = keys.current;

      if (phaseRef.current === "fly") {
        const steer = (k.r ? 1 : 0) - (k.l ? 1 : 0);
        if (assistRef.current) {
          // Attitude hold: the keys command a lean of up to 35 deg; releasing them levels the lander.
          const target = steer * 35 * P.DEG;
          s.w += ((target - s.a) * 6 - s.w * 4) * dt;
        } else {
          s.w += steer * TORQUE * dt; // raw thruster torque
          s.w *= 1 - Math.min(1, 1.6 * dt); // rate damping
        }
        s.a += s.w * dt;
        s.burn = k.t && s.fuel > 0;
        let ax = 0;
        let ay = -G_MOON;
        if (s.burn) {
          ax += Math.sin(s.a) * THRUST;
          ay += Math.cos(s.a) * THRUST;
          s.fuel = Math.max(0, s.fuel - dt / BURN_S);
        }
        s.vx += ax * dt;
        s.vy += ay * dt;
        s.x += s.vx * dt;
        s.y += s.vy * dt;
        if (Math.abs(s.x) > 1040) finish(true);
        else if (s.y - 2.2 <= ground(s.x)) {
          s.y = ground(s.x) + 2.2;
          s.burn = false;
          finish(false);
        }
      }

      /* ---- draw ---- */
      const dpr = Math.min(2, window.devicePixelRatio || 1);
      const W = cv.clientWidth;
      const H = cv.clientHeight;
      if (cv.width !== Math.round(W * dpr) || cv.height !== Math.round(H * dpr)) {
        cv.width = Math.round(W * dpr);
        cv.height = Math.round(H * dpr);
      }
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const alt = Math.max(0, s.y - 2.2 - ground(s.x));
      const target = P.clamp(W / (alt * 3.2 + 110), W / 2100, 7);
      s.scale += (target - s.scale) * Math.min(1, dt * 2.5);
      const sc = s.scale;
      const camX = P.clamp(s.x, -1050 + W / 2 / sc, 1050 - W / 2 / sc);
      const camY = s.y - (H * 0.12) / sc;
      const X = (x: number) => W / 2 + (x - camX) * sc;
      const Y = (y: number) => H * 0.42 - (y - camY) * sc;

      const sky = ctx.createLinearGradient(0, 0, 0, H);
      sky.addColorStop(0, "#02030a");
      sky.addColorStop(1, "#0a1020");
      ctx.fillStyle = sky;
      ctx.fillRect(0, 0, W, H);
      for (const st of stars) {
        ctx.fillStyle = "rgba(226,232,240,0.7)";
        ctx.fillRect(st[0] * W, st[1] * H, st[2], st[2]);
      }
      if (props.sunLit) {
        const sx = sunRight ? W - 70 : 70;
        const sy = H * 0.3;
        const g = ctx.createRadialGradient(sx, sy, 0, sx, sy, 150);
        g.addColorStop(0, "rgba(255,255,255,1)");
        g.addColorStop(0.06, "rgba(255,246,200,0.95)");
        g.addColorStop(0.2, "rgba(252,211,77,0.28)");
        g.addColorStop(1, "rgba(245,158,11,0)");
        ctx.fillStyle = g;
        ctx.fillRect(sx - 150, sy - 150, 300, 300);
      }
      if (props.earthVisible) {
        const ex = sunRight ? 90 : W - 90;
        const ey = 56;
        const g = ctx.createRadialGradient(ex - 5, ey - 5, 2, ex, ey, 17);
        g.addColorStop(0, "#93c5fd");
        g.addColorStop(0.6, "#2563eb");
        g.addColorStop(1, "#0b2a6b");
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(ex, ey, 16, 0, 6.283);
        ctx.fill();
        ctx.fillStyle = "rgba(255,255,255,0.5)";
        ctx.beginPath();
        ctx.ellipse(ex - 3, ey - 5, 9, 2.2, 0.4, 0, 6.283);
        ctx.ellipse(ex + 4, ey + 6, 7, 1.8, -0.3, 0, 6.283);
        ctx.fill();
      }

      // terrain body
      const x0 = Math.max(-1050, camX - W / 2 / sc - 10);
      const x1 = Math.min(1050, camX + W / 2 / sc + 10);
      const step = Math.max(2, 3 / sc);
      ctx.beginPath();
      ctx.moveTo(X(x0), H + 2);
      for (let x = x0; x <= x1; x += step) ctx.lineTo(X(x), Y(ground(x)));
      ctx.lineTo(X(x1), Y(ground(x1)));
      ctx.lineTo(X(x1), H + 2);
      ctx.closePath();
      const tg = ctx.createLinearGradient(0, H * 0.4, 0, H);
      tg.addColorStop(0, "#565a63");
      tg.addColorStop(1, "#15171d");
      ctx.fillStyle = tg;
      ctx.fill();
      // surface: sunlit faces bright, far faces dark; flat stretches marked green, hazards red
      ctx.lineCap = "round";
      for (let x = x0; x < x1; x += step) {
        const sl = slopeAt(x + step / 2);
        const facing = sunRight ? sl < 1.5 : sl > -1.5;
        ctx.strokeStyle = props.sunLit && facing ? "#e7e5dc" : "#6b7280";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(X(x), Y(ground(x)));
        ctx.lineTo(X(x + step), Y(ground(x + step)));
        ctx.stroke();
        const a = Math.abs(sl);
        ctx.strokeStyle = a <= P.SLOPE_SAFE_DEG ? "rgba(34,197,94,0.9)" : a > LIMITS.slope ? "rgba(239,68,68,0.9)" : "rgba(245,158,11,0.55)";
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(X(x), Y(ground(x)) + 6);
        ctx.lineTo(X(x + step), Y(ground(x + step)) + 6);
        ctx.stroke();
      }

      // lander
      const L = Math.max(sc * 4.4, 7);
      ctx.save();
      ctx.translate(X(s.x), Y(s.y));
      ctx.rotate(s.a);
      if (s.burn) {
        const fl = L * (1.1 + Math.random() * 0.7);
        const fg = ctx.createLinearGradient(0, L * 0.45, 0, L * 0.45 + fl);
        fg.addColorStop(0, "rgba(255,255,255,0.95)");
        fg.addColorStop(0.35, "rgba(253,224,71,0.8)");
        fg.addColorStop(1, "rgba(245,158,11,0)");
        ctx.fillStyle = fg;
        ctx.beginPath();
        ctx.moveTo(-L * 0.22, L * 0.45);
        ctx.lineTo(0, L * 0.45 + fl);
        ctx.lineTo(L * 0.22, L * 0.45);
        ctx.fill();
      }
      if (L < 12) {
        ctx.strokeStyle = "rgba(6,182,212,0.7)";
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.arc(0, 0, 16, 0, 6.283);
        ctx.stroke();
      }
      ctx.strokeStyle = "#cbd5e1";
      ctx.lineWidth = Math.max(1, L * 0.07);
      ctx.beginPath();
      ctx.moveTo(-L * 0.35, L * 0.15);
      ctx.lineTo(-L * 0.75, L * 0.5);
      ctx.moveTo(L * 0.35, L * 0.15);
      ctx.lineTo(L * 0.75, L * 0.5);
      ctx.moveTo(-L * 0.92, L * 0.5);
      ctx.lineTo(-L * 0.58, L * 0.5);
      ctx.moveTo(L * 0.58, L * 0.5);
      ctx.lineTo(L * 0.92, L * 0.5);
      ctx.stroke();
      ctx.fillStyle = "#c9a24a";
      ctx.beginPath();
      ctx.moveTo(-L * 0.5, L * 0.3);
      ctx.lineTo(-L * 0.5, -L * 0.1);
      ctx.lineTo(-L * 0.28, -L * 0.42);
      ctx.lineTo(L * 0.28, -L * 0.42);
      ctx.lineTo(L * 0.5, -L * 0.1);
      ctx.lineTo(L * 0.5, L * 0.3);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = "#e2e8f0";
      ctx.fillRect(-L * 0.2, -L * 0.62, L * 0.4, L * 0.22);
      ctx.fillStyle = "#555A8C";
      ctx.fillRect(-L * 0.16, L * 0.3, L * 0.32, L * 0.16);
      ctx.restore();

      hudT += dt;
      if (hudT > 0.09) {
        hudT = 0;
        setHud({ alt, vv: -s.vy, vh: s.vx, tilt: s.a / P.DEG, fuel: s.fuel });
      }
    };
    raf = requestAnimationFrame(frame);
    return () => cancelAnimationFrame(raf);
  }, [ground, slopeAt, finish, props.sunAz, props.sunLit, props.earthVisible]);

  const hold = (key: "l" | "r" | "t") => ({
    onPointerDown: (e: React.PointerEvent) => {
      e.preventDefault();
      keys.current[key] = true;
      if (phaseRef.current === "ready") setPhase("fly");
    },
    onPointerUp: () => (keys.current[key] = false),
    onPointerLeave: () => (keys.current[key] = false),
    onPointerCancel: () => (keys.current[key] = false),
  });
  const okCls = (ok: boolean) => (ok ? "ok" : "bad");

  return (
    <div className="lander">
      <div className="lander-stage">
        <canvas ref={cvRef} aria-label="Landing simulator view" />
        <div className="lander-hud mono">
          <span>ALT <b>{hud.alt.toFixed(0)} m</b></span>
          <span className={okCls(hud.vv <= LIMITS.vVert)}>DESCENT <b>{hud.vv.toFixed(1)} m/s</b></span>
          <span className={okCls(Math.abs(hud.vh) <= LIMITS.vHoriz)}>DRIFT <b>{Math.abs(hud.vh).toFixed(1)} m/s {hud.vh > 0.05 ? "→" : hud.vh < -0.05 ? "←" : ""}</b></span>
          <span className={okCls(Math.abs(hud.tilt) <= LIMITS.tilt)}>TILT <b>{Math.abs(hud.tilt).toFixed(0)}°</b></span>
          <span className="fuel">
            FUEL
            <i>
              <em style={{ width: hud.fuel * 100 + "%", background: hud.fuel < 0.2 ? "#FF5C7A" : "#4FD1E8" }} />
            </i>
          </span>
        </div>
        {phase === "ready" && (
          <div className="lander-msg">
            <h3>Land on a green stretch</h3>
            <p>
              Hold <b>↑</b> (or Space) to fire the engine. Hold <b>←</b> or <b>→</b> to lean; let go and the lander
              levels itself. You start drifting right, so lean left and burn to stop, then come down slowly.
            </p>
            <button className="btn primary" onClick={() => setPhase("fly")}>
              Start descent
            </button>
          </div>
        )}
        {result && (
          <div className={"lander-msg " + (result.ok ? "good" : "fail")}>
            <h3>
              {result.title} · grade {result.grade}
            </h3>
            {result.ok ? (
              <p>
                Touchdown at {result.vVert.toFixed(1)} m/s on a {result.slope.toFixed(0)}° slope with {(result.fuel * 100).toFixed(0)}% fuel left.{" "}
                {result.sun ? "The spot is in sunlight" : "The spot is in shadow, so no solar power"}
                {result.earth ? " and Earth is in view." : " and Earth is hidden, so no radio link."}
              </p>
            ) : (
              <ul>
                {result.reasons.map((r) => (
                  <li key={r}>{r}</li>
                ))}
              </ul>
            )}
            <button className="btn primary" onClick={reset}>
              {result.ok ? "Fly again" : "Try again"}
            </button>
          </div>
        )}
      </div>
      <div className="lander-pad" role="group" aria-label="Flight controls">
        <button className="btn" {...hold("l")} aria-label="Tilt left">⟲ Tilt left</button>
        <button className="btn glow" {...hold("t")} aria-label="Fire engine">▲ Engine</button>
        <button className="btn" {...hold("r")} aria-label="Tilt right">Tilt right ⟳</button>
        <button className="btn" onClick={reset}>Restart</button>
        <button
          className="btn"
          aria-pressed={assist}
          onClick={() => {
            assistRef.current = !assist;
            setAssist(!assist);
          }}
        >
          Auto-level: {assist ? "on" : "off"}
        </button>
      </div>
    </div>
  );
}
